def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers.

    The primes may repeat, for example 8 = 2 * 2 * 2.
    """
    if a < 2:
        return False

    count = 0
    divisor = 2

    while divisor * divisor <= a:
        while a % divisor == 0:
            count += 1
            a //= divisor
            if count > 3:
                return False
        divisor += 1

    if a > 1:
        count += 1

    return count == 3

